                {
                    z[i] = math.max(r, (double)0) + zwFloor;
                    w[i] = math.max(-r, (double)0) + zwFloor;
                }
                else
                {
                    z[i] = math.max(r, (double)0);
                    w[i] = math.max(-r, (double)0);
                }
