                    design.ApplyT(in qCorr, ref tmpN);
                    for (int j = 0; j < n; j++) rhs2[j] = rhs[j] + tmpN[j];
                    for (int j = 0; j < n; j++) tmpN[j] = rhs2[j] * dscale[j];
                    CHOP.decompSolve(ref L, in P, rank, ref tmpN, ref ws);
                    for (int j = 0; j < n; j++) dy[j] = tmpN[j] * dscale[j];

